\label{lem:circle-area-kernels}
For $u>1$, $\beta>-1$ and $\lambda>\beta+2$,
\[
 \int_0^{2\pi}\frac{d\theta}{|1-re^{i\theta}|^u}
       \le C(1-r)^{1-u},\qquad 0\le r<1,
\]
and
\begin{equation}\label{eq:weighted-area-kernel}
 \int_{\mathbb D}\frac{(1-|z|^2)^\beta}{|1-\overline wz|^\lambda}\,dA(z)
       \le C(1-|w|^2)^{\beta+2-\lambda},\qquad w\in\mathbb D.
\end{equation}

\label{lem:F-little-approximation}
Let $0<p<\infty$, $q>-2$, $s>0$ and $q+s>-1$.
For $f\in F(p,q,s)$, the following conditions are equivalent:
\begin{enumerate}
 \renewcommand{\textup{(\arabic{enumi})}}{\textup{(\arabic{enumi})}}
 \setlength{\itemsep}{2pt}\setlength{\parskip}{0pt}
 \item $f\in F_0(p,q,s)$.
 \item $\displaystyle\lim_{|I|\downarrow0}\frac{1}{|I|^s}
       \int_{S(I)}|f'(z)|^p(1-|z|^2)^{q+s}\,dA(z)=0$.
 \item $\displaystyle\lim_{\rho\uparrow1}
                         \|f-C_\rho f\|_{F(p,q,s)}=0$.
 \item $f$ is in the closure of the polynomials in $F(p,q,s)$.
\end{enumerate}
In particular, $F_0(p,q,s)$ is closed and complete, and every
function analytic on a neighborhood of $\overline{\mathbb D}$ belongs
to it. Each $C_\rho$, $\rho<1$, maps $F(p,q,s)$ compactly into
$F_0(p,q,s)$. For $s=0$ (and hence $q>-1$), polynomials are dense
in $F(p,q,0)$ as well.

\label{lem:two-kernels}
Fix $A>0$, positive integers $M$ and $n$, and $0<r<\infty$. For
$u=0,1$, put
\[
 g_{j,l,u}(z)=\frac{\delta_j^{M+u-A}}
                    {(1-\overline{a_{j,l}}z)^{M+u}}.
\]
Then, for $w\in Q_{j,l}$ and $x,y\in\mathbb C$,
\begin{equation}\label{eq:two-kernels}
 \frac{|x|^r}{\delta_j^{r(A+n-1)}}
 +\frac{|y|^r}{\delta_j^{r(A+n)}}
 \le C\sum_{u=0}^1
       |xg_{j,l,u}^{(n-1)}(w)+yg_{j,l,u}^{(n)}(w)|^r.
\end{equation}
The constant is independent of $j,l,w,x,y$.

\label{prop:radial-majorant}
Let $0<p<\infty$, $0<q\le\infty$ and $\alpha>0$ satisfy
$\alpha+1/p>1$. Let $\phi\in H(\mathbb D)$ and let $\varphi$ be an analytic
self-map of $\mathbb D$. The following conditions are equivalent:
\begin{enumerate}
 \renewcommand{\textup{(\arabic{enumi})}}{\textup{(\arabic{enumi})}}
 \setlength{\itemsep}{2pt}
 \setlength{\parskip}{0pt}
 \item There is a nonnegative Borel function $G$ on $\mathbb D$ such that
 \[
  \sup_{0\le r<1}\int_0^{2\pi}G(re^{i\theta})^p\,d\theta<\infty,
 \]
 and $|D_{\phi,\varphi}^{0}f(z)|\le G(z)$ for every $z\in\mathbb D$ and
 every $f\in S(p,q,\alpha)$ with $\|f\|_{S(p,q,\alpha)}\le1$.
 \item The symbols satisfy
 \[
  \sup_{0\le r<1}\int_0^{2\pi}
  \frac{|\phi(re^{i\theta})|^p}
  {(1-|\varphi(re^{i\theta})|^2)^{\alpha p+1-p}}\,d\theta<\infty.
 \]
\end{enumerate}
Either condition implies that
$D_{\phi,\varphi}^{0}:S(p,q,\alpha)\to H^p$ is bounded. The converse fails in general,
even when the operator is compact.

\label{thm:derivative-hardy}
Let $0<p,q\le\infty$, $0<r<\infty$, $\alpha>0$ and $n\ge1$ be an
integer. Let $\phi\in H(\mathbb D)$ and let $\varphi$ be an analytic
self-map of $\mathbb D$. The following conditions are equivalent:
\begin{enumerate}
 \renewcommand{\textup{(\arabic{enumi})}}{\textup{(\arabic{enumi})}}
 \setlength{\itemsep}{2pt}\setlength{\parskip}{0pt}
 \item $D_{\phi,\varphi}^{n}:S(p,q,\alpha)\to H^r$ is bounded.
 \item $D_{\phi,\varphi}^{n-1}:H(p,q,\alpha)\to H^r$ is bounded.
 \item $\displaystyle\sup_{0\le t<1}
          \|\{d_{t,j,l}^{(n-1)}\}_{j,l}\|_{\ell^{P,Q}}<\infty$.
\end{enumerate}
Condition \textup{(3)} is the four-case test in
\eqref{eq:mixed-four-cases} with $d=d_t^{(n-1)}$, uniformly in $t$.
When these conditions hold, the operators in \textup{(1)} and
\textup{(2)} have equal norms and equal essential norms. In particular,
\[
 \begin{aligned}
 \|D_{\phi,\varphi}^{n}\|_{S(p,q,\alpha)\to H^r}^{\,r}
 &\approx\sup_{0\le t<1}
          \|\{d_{t,j,l}^{(n-1)}\}_{j,l}\|_{\ell^{P,Q}},\\
 \|D_{\phi,\varphi}^{n}\|_{e,S(p,q,\alpha)\to H^r}^{\,r}
 &\approx\lim_{J\to\infty}\sup_{0\le t<1}
          \|\{d_{t,j,l}^{(n-1)}:j\ge J\}\|_{\ell^{P,Q}}.
 \end{aligned}
\]
Under these boundedness conditions, the operator in \textup{(1)} is
compact if and only if the operator in \textup{(2)} is compact,
equivalently, if and only if the last limit is zero.

\label{thm:mixed-boundary}
Let $0<p,q\le\infty$, $0<r<\infty$, $\alpha>0$, and let
$n\ge0$ be an integer. Let $\phi\not\equiv0$ be analytic and let $\varphi$ be an analytic
self-map of $\mathbb D$. Then
$D_{\phi,\varphi}^n:H(p,q,\alpha)\to H^r$ is bounded if and only if
\begin{enumerate}
 \renewcommand{\textup{(\arabic{enumi})}}{\textup{(\arabic{enumi})}}
 \setlength{\itemsep}{2pt}\setlength{\parskip}{0pt}
 \item $\phi\in H^r$;
 \item $|\varphi^*|<1$ almost everywhere on $\partial\mathbb D$;
 \item the finite measure
 \[
  \mu_{\partial}(E)=\int_{\{\zeta:\varphi^*(\zeta)\in E\}}
                         |\phi^*(\zeta)|^r\,dm(\zeta)
 \]
 satisfies $d_{\partial}^{(n)}\in\ell^{P,Q}$, where
 $d_{\partial,j,l}^{(n)}=
 \delta_j^{-r(n+\alpha+1/p)}\mu_{\partial}(Q_{j,l})$.
\end{enumerate}
The norm in \textup{(3)} is given by the four explicit cases in
\eqref{eq:mixed-four-cases}, with no radial supremum. When these
conditions hold,
\[
 \begin{aligned}
  \|D_{\phi,\varphi}^n\|^{r}
       &\approx\|d_{\partial}^{(n)}\|_{\ell^{P,Q}},\\
  \|D_{\phi,\varphi}^n\|_e^{r}
       &\approx\lim_{J\to\infty}
           \|\{d_{\partial,j,l}^{(n)}:j\ge J\}\|_{\ell^{P,Q}}.
 \end{aligned}
\]
In particular, compactness is equivalent to vanishing of the last
limit. If $\phi\equiv0$, the operator is zero and no condition on
$\varphi^*$ is required.

\label{ex:Hardy-critical-q}
The condition $q>r$ in Corollary~\ref{cor:Hardy-automatic-compactness}
cannot be replaced by $q\ge r$. For $\phi(z)=1-z$ and
$\varphi(z)=(1+z)/2$, the operator
$D_{\phi,\varphi}^0:H(2,2,1/2)\to H^2$ is bounded but not compact.

\label{lem:positive-Carleson-kernel}
Let $s\ge0$, $\beta>-1$, $\beta+2>s$ and $\lambda>\beta+2$.
If $\|\mu\|_s<\infty$, define a positive measure $\nu$ by
\[
 d\nu(z)=(1-|z|^2)^\beta
       \left(\int_{\mathbb D}
          \frac{(1-|w|^2)^{\lambda-\beta-2}}
               {|1-\overline wz|^\lambda}\,d\mu(w)\right)dA(z).
\]
Then $\|\nu\|_s\le C\|\mu\|_s$.

\label{prop:explicit-sequence}
For every $0<p,r<\infty$, $s\ge0$ and nonnegative array $v$,
\begin{equation}\label{eq:sequence-explicit-equivalence}
       \mathfrak D_{p,s;r}(v)^r\approx\mathcal C_{p,s;r}(v),
\end{equation}
with constants independent of $v$ and of finite truncations.
The equality in the cases $s=0$ is exact.
For $0<s\le1$ and $r\ge p$, the finite-depth integrand in
\eqref{eq:explicit-sequence-functional} is the least dyadic
$s$-covering cost of the arcs satisfying $v_I/b_I>t$.
In particular, when $s=1$ and $r\ge p$,
\begin{equation}\label{eq:critical-shadow-maximal}
 \mathcal C_{p,1;r}(v)
     =\int_{\partial\mathbb D}
        \sup_{\substack{j,l\ge0\,;\ I_{j,l}\ni\zeta}}
                    \frac{v_{j,l}}{|I_{j,l}|}\,dm(\zeta),
\end{equation}
where $l$ always has its prescribed finite range in row $j$.

\label{thm:F-boundedness}
Let $0<p_i<\infty$, $q_i>-2$, $0\le s_i<\infty$ and $q_i+s_i>-1$
for $i=1,2$. Let $n\ge1$ be an integer, let
$\phi\in H(\mathbb D)$ and let $\varphi$ be an analytic self-map of
$\mathbb D$. The following conditions are equivalent:
\begin{enumerate}
 \renewcommand{\textup{(\arabic{enumi})}}{\textup{(\arabic{enumi})}}
 \setlength{\itemsep}{2pt}\setlength{\parskip}{0pt}
 \item $D_{\phi,\varphi}^{n}:F(p_1,q_1,s_1)\to F(p_2,q_2,s_2)$ is
       bounded.
 \item $\displaystyle\sup_{a\in\mathbb D}
                     \mathcal C_{p_1,s_1;p_2}(v_a)<\infty$.
\end{enumerate}
The quantity in \textup{(2)} is given explicitly by
\eqref{eq:explicit-sequence-functional}: its middle range uses the
covering rule for $p_2\ge p_1$ and the power rule for $p_2<p_1$.
When these conditions hold,
\[
 \|D_{\phi,\varphi}^{n}\|_{F(p_1,q_1,s_1)\to F(p_2,q_2,s_2)}
 \approx
 \frac{|\phi(0)|}{(1-|\varphi(0)|^2)^{b_n}}
       +\left(\sup_{a\in\mathbb D}\mathcal C_{p_1,s_1;p_2}(v_a)\right)^{1/p_2}.
\]
The comparison constants depend only on the two parameter triples,
$n$ and the fixed partition. In particular, neither $p_1\le p_2$ nor
$p_i\ge1$ is required.

\label{cor:F-explicit-regions}
Let $0<p_i<\infty$, $q_i>-2$, $0\le s_i<\infty$ and
$q_i+s_i>-1$ for $i=1,2$, and let $n\ge1$.
Use the symbols, $b_n$, $\lambda_a$ and $v_a$ from
Theorem~\ref{thm:F-boundedness}.
\begin{enumerate}
 \renewcommand{\textup{(\arabic{enumi})}}{\textup{(\arabic{enumi})}}
 \setlength{\itemsep}{3pt}\setlength{\parskip}{0pt}
 \item If $s_1=0$, boundedness is equivalent to
 \[
 \begin{cases}
  \displaystyle\sup_{a,j,l}v_{a,j,l}<\infty,&p_1\le p_2,\\[1mm]
  \displaystyle\sup_a
       \left(\sum_{j,l}v_{a,j,l}^{p_1/(p_1-p_2)}
       \right)^{(p_1-p_2)/p_1}<\infty,&p_2<p_1.
 \end{cases}
 \]
 \item If $0<s_1\le1$, boundedness is equivalent to
 \[
  \sup_{a\in\mathbb D}\lim_{N\to\infty}
      \int_0^\infty R_{\partial\mathbb D}^{(N)}(t;v_a)\,dt<\infty.
 \]
 Use the covering rule \eqref{eq:tree-superlinear-rule} when
 $p_2\ge p_1$, and the power rule \eqref{eq:tree-sublinear-rule}
 when $p_2<p_1$, with $\theta=p_2/p_1$ and $b_I=|I|^{s_1}$.
 In the particular case $s_1=1$ and $p_2\ge p_1$, this is the
 boundary integral condition
 \[
  \sup_a\int_{\partial\mathbb D}
     \sup_{I_{j,l}\ni\zeta}\frac{v_{a,j,l}}{|I_{j,l}|}\,dm(\zeta)
       <\infty.
 \]
 \item If $s_1>1$, boundedness is equivalent to
 \begin{equation}\label{eq:F-Bloch-source-integral}
 \sup_a\int_{\mathbb D}
  \left(
    \frac{|\phi'(z)|^{p_2}}
         {(1-|\varphi(z)|^2)^{p_2b_n}}
    +\frac{|\phi(z)\varphi'(z)|^{p_2}}
         {(1-|\varphi(z)|^2)^{p_2(b_n+1)}}
  \right)d\lambda_a(z)<\infty.
 \end{equation}
\end{enumerate}
In each case the $p_2$th power of the operator norm is comparable
to the stated quantity plus
$|\phi(0)|^{p_2}(1-|\varphi(0)|^2)^{-p_2b_n}$.
Under boundedness, its essential norm to the power $p_2$ is comparable
to
\[
 \lim_{J\to\infty}\sup_{a\in\mathbb D}
      \mathcal C_{p_1,s_1;p_2}(\{v_{a,j,l}:j\ge J\}).
\]
In (1)--(2), evaluate the indicated formula after setting all earlier
entries to zero. In (3), the equivalent tail is obtained by restricting
the symbol integral to $|\varphi(z)|\ge R$, taking $\sup_a$ first,
and then letting $R\uparrow1$. Compactness is equivalent to a zero limit.
The same replacements apply to the operators on little spaces in
Theorem~\ref{thm:F-little-operators}, with its stated symbol
memberships unchanged.

\label{cor:Dirichlet-interior}
Let $\beta>-1$, let $n\ge1$ be an integer, let
$\phi\in\mathcal D_\beta$, and let $\varphi$ be an analytic self-map
of $\mathbb D$ with $\|\varphi\|_\infty<1$. The following conditions
are equivalent:
\begin{enumerate}
 \renewcommand{\textup{(\arabic{enumi})}}{\textup{(\arabic{enumi})}}
 \setlength{\itemsep}{2pt}\setlength{\parskip}{0pt}
 \item $D_{\phi,\varphi}^{n}:\mathcal D_\beta\to\mathcal D_\beta$
       is bounded.
 \item $D_{\phi,\varphi}^{n}:\mathcal D_\beta\to\mathcal D_\beta$
       is compact.
 \item $\phi\varphi\in\mathcal D_\beta$.
\end{enumerate}
Condition \textup{(3)} is also equivalent to $\phi\varphi'\in A_\beta^2$.

\label{thm:Dirichlet-Schatten}
Let $\beta_1\in\mathbb R$, $\beta_2>-1$, and let $n\ge0$ be
an integer such that $\beta_1+2n>1$. Let $0<t<\infty$,
$\phi\in H(\mathbb D)$, and let $\varphi$ be an analytic self-map of
$\mathbb D$. The following conditions are equivalent:
\begin{enumerate}
 \renewcommand{\textup{(\arabic{enumi})}}{\textup{(\arabic{enumi})}}
 \setlength{\itemsep}{2pt}\setlength{\parskip}{0pt}
 \item $D_{\phi,\varphi}^{n}:\mathcal D_{\beta_1}\to
                  \mathcal D_{\beta_2}$ belongs to $\mathcal S_t$.
 \item $\displaystyle\sum_{j,l}v_{j,l}^{t/2}<\infty$.
 \item For one, equivalently every, fixed $0<\eta<1$,
 \[
  \int_{\mathbb D}\left(
   \frac{\nu_0(\Delta(w,\eta))}{(1-|w|^2)^{\beta_1+2n}}
   +\frac{\nu_1(\Delta(w,\eta))}{(1-|w|^2)^{\beta_1+2n+2}}
       \right)^{t/2}\frac{dA(w)}{(1-|w|^2)^2}<\infty.
 \]
\end{enumerate}
When these conditions hold,
\begin{equation}\label{eq:Dirichlet-Schatten-norm}
 \|D_{\phi,\varphi}^{n}\|_{\mathcal S_t}^t
   \approx
   \frac{|\phi(0)|^t}
        {(1-|\varphi(0)|^2)^{t(\beta_1+2n)/2}}
           +\sum_{j,l}v_{j,l}^{t/2}.
\end{equation}
In particular, Hilbert--Schmidt membership is equivalent to
\[
 \int_{\mathbb D}\left(
  \frac{|\phi'(z)|^2}{(1-|\varphi(z)|^2)^{\beta_1+2n}}
  +\frac{|\phi(z)\varphi'(z)|^2}
        {(1-|\varphi(z)|^2)^{\beta_1+2n+2}}
       \right)(1-|z|^2)^{\beta_2}\,dA(z)<\infty.
\]
The sum in \eqref{eq:Dirichlet-Schatten-norm} may also be replaced
by the integral in \textup{(3)}. For $t=2$ it may be replaced by
the preceding direct symbol integral.
All comparison constants depend only on $\beta_1,\beta_2,n,t$ and
the fixed partition (and on $\eta$ for the disk-integral version).
